changeSet.sql:
ALTER TABLE finances.stock_holdings
    ADD COLUMN status finances.holding_status NOT NULL DEFAULT 'ACTIVE';
ALTER TABLE finances.crypto_holdings
    ADD COLUMN status finances.holding_status NOT NULL DEFAULT 'ACTIVE';
ALTER TABLE finances.fund_holdings
    ADD COLUMN status finances.holding_status NOT NULL DEFAULT 'ACTIVE';

rollback.sql:
ALTER TABLE finances.fund_holdings DROP COLUMN status;
ALTER TABLE finances.crypto_holdings DROP COLUMN status;
ALTER TABLE finances.stock_holdings DROP COLUMN status;

changeSet.sql:
CREATE INDEX idx_results_stock_holding_id ON finances.results (stock_holding_id);
CREATE INDEX idx_results_crypto_holding_id ON finances.results (crypto_holding_id);
CREATE INDEX idx_results_fund_holding_id ON finances.results (fund_holding_id);
CREATE INDEX idx_results_result_date ON finances.results (result_date);

rollback.sql:
DROP INDEX finances.idx_results_result_date;
DROP INDEX finances.idx_results_fund_holding_id;
DROP INDEX finances.idx_results_crypto_holding_id;
DROP INDEX finances.idx_results_stock_holding_id;

changeSet.sql:
DROP VIEW finances.holdings_report_rows; DROP VIEW finances.holdings_overview;
CREATE VIEW finances.holdings_overview AS SELECT stock_holdings.id AS holding_id, stock_holdings.external_id, stock_holdings.wallet_id, 'STOCKS'::finances.wallet_kind AS kind, stock_holdings.status, stock_holdings.name, stock_holdings.ticker, stock_types.name AS type_label, stock_holdings.current_price, COALESCE(SUM(stock_lots.quantity), 0) - ( SELECT COALESCE(SUM(results.quantity), 0) FROM finances.results WHERE results.stock_holding_id = stock_holdings.id ) AS quantity, COALESCE(SUM(stock_lots.quantity * stock_lots.price), 0) - ( SELECT COALESCE(SUM(results.cost_basis), 0) FROM finances.results WHERE results.stock_holding_id = stock_holdings.id ) AS cost_basis, stock_holdings.current_price * ( COALESCE(SUM(stock_lots.quantity), 0) - ( SELECT COALESCE(SUM(results.quantity), 0) FROM finances.results WHERE results.stock_holding_id = stock_holdings.id ) ) AS current_value FROM finances.stock_holdings JOIN finances.stock_types ON stock_types.id = stock_holdings.stock_type_id LEFT JOIN finances.stock_lots ON stock_lots.stock_holding_id = stock_holdings.id GROUP BY stock_holdings.id, stock_holdings.external_id, stock_holdings.wallet_id, stock_holdings.status, stock_holdings.name, stock_holdings.ticker, stock_types.name, stock_holdings.current_price
UNION ALL
SELECT crypto_holdings.id AS holding_id, crypto_holdings.external_id, crypto_holdings.wallet_id, 'CRYPTO'::finances.wallet_kind AS kind, crypto_holdings.status, crypto_holdings.name, crypto_holdings.ticker, NULL::TEXT AS type_label, crypto_holdings.current_price, COALESCE(SUM(crypto_lots.quantity), 0) - ( SELECT COALESCE(SUM(results.quantity), 0) FROM finances.results WHERE results.crypto_holding_id = crypto_holdings.id ) AS quantity, COALESCE(SUM(crypto_lots.quantity * crypto_lots.price), 0) - ( SELECT COALESCE(SUM(results.cost_basis), 0) FROM finances.results WHERE results.crypto_holding_id = crypto_holdings.id ) AS cost_basis, crypto_holdings.current_price * ( COALESCE(SUM(crypto_lots.quantity), 0) - ( SELECT COALESCE(SUM(results.quantity), 0) FROM finances.results WHERE results.crypto_holding_id = crypto_holdings.id ) ) AS current_value FROM finances.crypto_holdings LEFT JOIN finances.crypto_lots ON crypto_lots.crypto_holding_id = crypto_holdings.id GROUP BY crypto_holdings.id, crypto_holdings.external_id, crypto_holdings.wallet_id, crypto_holdings.status, crypto_holdings.name, crypto_holdings.ticker, crypto_holdings.current_price
UNION ALL
SELECT fund_holdings.id AS holding_id, fund_holdings.external_id, fund_holdings.wallet_id, 'FUNDS'::finances.wallet_kind AS kind, fund_holdings.status, fund_holdings.name, NULL::TEXT AS ticker, fund_types.name AS type_label, NULL::NUMERIC AS current_price, NULL::NUMERIC AS quantity, COALESCE(SUM(fund_contributions.amount), 0) - ( SELECT COALESCE(SUM(results.cost_basis), 0) FROM finances.results WHERE results.fund_holding_id = fund_holdings.id ) AS cost_basis, fund_holdings.current_value FROM finances.fund_holdings JOIN finances.fund_types ON fund_types.id = fund_holdings.fund_type_id LEFT JOIN finances.fund_contributions ON fund_contributions.fund_holding_id = fund_holdings.id GROUP BY fund_holdings.id, fund_holdings.external_id, fund_holdings.wallet_id, fund_holdings.status, fund_holdings.name, fund_types.name, fund_holdings.current_value;
CREATE VIEW finances.holdings_report_rows AS SELECT MIN(external_id::TEXT)::UUID AS external_id, wallet_id, kind, name, ticker, type_label, CASE WHEN SUM(quantity) IS NOT NULL AND SUM(quantity) <> 0 THEN SUM(current_value) / SUM(quantity) ELSE MAX(current_price) END AS current_price, SUM(quantity) AS quantity, SUM(cost_basis) AS cost_basis, SUM(current_value) AS current_value FROM finances.holdings_overview WHERE status = 'ACTIVE' GROUP BY wallet_id, kind, name, ticker, type_label;

rollback.sql:
DROP VIEW finances.holdings_report_rows; DROP VIEW finances.holdings_overview;
CREATE VIEW finances.holdings_overview AS SELECT sh.external_id, sh.wallet_id, 'STOCKS'::finances.wallet_kind AS kind, sh.name, sh.ticker, st.name AS type_label, sh.current_price, COALESCE(SUM(sl.quantity), 0) AS quantity, COALESCE(SUM(sl.quantity * sl.price), 0) AS cost_basis, sh.current_price * COALESCE(SUM(sl.quantity), 0) AS current_value FROM finances.stock_holdings sh JOIN finances.stock_types st ON st.id = sh.stock_type_id LEFT JOIN finances.stock_lots sl ON sl.stock_holding_id = sh.id GROUP BY sh.id, sh.external_id, sh.wallet_id, sh.name, sh.ticker, st.name, sh.current_price
UNION ALL
SELECT ch.external_id, ch.wallet_id, 'CRYPTO'::finances.wallet_kind AS kind, ch.name, ch.ticker, NULL::TEXT AS type_label, ch.current_price, COALESCE(SUM(cl.quantity), 0) AS quantity, COALESCE(SUM(cl.quantity * cl.price), 0) AS cost_basis, ch.current_price * COALESCE(SUM(cl.quantity), 0) AS current_value FROM finances.crypto_holdings ch LEFT JOIN finances.crypto_lots cl ON cl.crypto_holding_id = ch.id GROUP BY ch.id, ch.external_id, ch.wallet_id, ch.name, ch.ticker, ch.current_price
UNION ALL
SELECT fh.external_id, fh.wallet_id, 'FUNDS'::finances.wallet_kind AS kind, fh.name, NULL::TEXT AS ticker, ft.name AS type_label, NULL::NUMERIC AS current_price, NULL::NUMERIC AS quantity, COALESCE(SUM(fc.amount), 0) AS cost_basis, fh.current_value FROM finances.fund_holdings fh JOIN finances.fund_types ft ON ft.id = fh.fund_type_id LEFT JOIN finances.fund_contributions fc ON fc.fund_holding_id = fh.id GROUP BY fh.id, fh.external_id, fh.wallet_id, fh.name, ft.name, fh.current_value;
CREATE VIEW finances.holdings_report_rows AS SELECT MIN(external_id::TEXT)::UUID AS external_id, wallet_id, kind, name, ticker, type_label, CASE WHEN SUM(quantity) IS NOT NULL AND SUM(quantity) <> 0 THEN SUM(current_value) / SUM(quantity) ELSE MAX(current_price) END AS current_price, SUM(quantity) AS quantity, SUM(cost_basis) AS cost_basis, SUM(current_value) AS current_value FROM finances.holdings_overview GROUP BY wallet_id, kind, name, ticker, type_label;
